    detailHeaderEl: "[data-detail-name]",
    detailChipEl: "[data-detail-chip]",
    detailDeadlineEl: "[data-detail-deadline]",
    detailChartEl: "[data-detail-chart]",
    detailTargetEl: "[data-detail-target]",
